command:
if (!game.user.isGM) return ui.notifications.warn('Level Up Unit is GM-only.');

const MAX_LEVEL = 30;
const units = (canvas.tokens?.controlled ?? []).filter(token => token.actor?.type === 'Character');
if (units.length !== 1) return ui.notifications.warn('Select exactly one unit.');

const unit = units[0].actor;
const from = Number(unit.system.progression?.level) || 1;
if (from >= MAX_LEVEL) return ui.notifications.warn(`${unit.name} is already at max level (${MAX_LEVEL}).`);

const result = await game.emblemRpg.api.character.progression.levelUp({ actorUuid: unit.uuid });
console.log(`emblem-rpg | Level Up Unit — ${unit.name}`, result.ok ? result.data : result);
